        private readonly struct LockToken : IDisposable
        {
            private readonly object t_lockObject;

            public LockToken(object lockObject)
            {
                Debug.Assert(lockObject != null);

                t_lockObject = lockObject;

                Debug.Assert(!Monitor.IsEntered(t_lockObject));

#if DEBUG
                bool success = Monitor.TryEnter(t_lockObject, 10000);
                Debug.Assert(success, "Timed out waiting for queue lock");
#else
                Monitor.Enter(t_lockObject);
#endif
            }

            public void Dispose()
            {
                Debug.Assert(Monitor.IsEntered(t_lockObject));
                Monitor.Exit(t_lockObject);
            }
        }
